import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.Cj_fzHAr.js";const p=JSON.parse('{"title":"¿Qué es Build & Serve?","description":"","frontmatter":{},"headers":[],"relativePath":"guia-inicio/index.md","filePath":"guia-inicio/index.md"}'),i={name:"guia-inicio/index.md"};function n(s,a,d,l,c,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="¿que-es-build-serve" tabindex="-1">¿Qué es Build &amp; Serve? <a class="header-anchor" href="#¿que-es-build-serve" aria-label="Permalink to &quot;¿Qué es Build &amp; Serve?&quot;">​</a></h1><p><strong>Build &amp; Serve</strong> es una plataforma para gestionar la <strong>Seguridad y Salud en el Trabajo (SST)</strong> de las obras de construcción de forma digital. Reemplaza las carpetas de papel por un sistema único donde centralizas documentos, firmas, capacitaciones e incidentes, con el cumplimiento del <strong>Supremo Decreto 44 (DS 44)</strong> integrado.</p><p>En palabras simples: <strong>todo el papeleo de prevención de riesgos de tu obra, en un solo lugar, firmado digitalmente y siempre disponible</strong> — incluso desde el teléfono y sin conexión.</p><p>Desarrollada por <strong>The Code Cookers</strong> para el Hackathon CChC 2025 — <em>Seguridad sin Papeleo</em>, en colaboración con la Cámara Chilena de la Construcción.</p><h2 id="¿para-quien-es" tabindex="-1">¿Para quién es? <a class="header-anchor" href="#¿para-quien-es" aria-label="Permalink to &quot;¿Para quién es?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Si eres…</th><th>La plataforma te ayuda a…</th></tr></thead><tbody><tr><td><strong>Empresa constructora</strong></td><td>Cumplir el DS 44 sin carpetas físicas ni papeleo disperso.</td></tr><tr><td><strong>Prevencionista</strong></td><td>Gestionar en un solo lugar documentos, matrices de riesgo y capacitaciones.</td></tr><tr><td><strong>Jefe de obra / Supervisor</strong></td><td>Capturar firmas y registrar actividades directamente en terreno.</td></tr><tr><td><strong>Trabajador</strong></td><td>Firmar documentos y registrar asistencia desde el móvil, incluso sin conexión.</td></tr></tbody></table><h2 id="¿que-problemas-resuelve" tabindex="-1">¿Qué problemas resuelve? <a class="header-anchor" href="#¿que-problemas-resuelve" aria-label="Permalink to &quot;¿Qué problemas resuelve?&quot;">​</a></h2><ul><li><strong>Papeleo disperso</strong> → documentos centralizados y firmados digitalmente.</li><li><strong>Cumplimiento manual del DS 44</strong> → documentos obligatorios que se preparan solos al crear la obra.</li><li><strong>Firmas en papel</strong> → firma digital con PIN, con registro de fecha, hora y verificación.</li><li><strong>Sin señal en obra</strong> → firma sin conexión que se sincroniza automáticamente después.</li><li><strong>Matrices de riesgo lentas de hacer</strong> → generación asistida por inteligencia artificial.</li></ul><h2 id="¿como-empiezo" tabindex="-1">¿Cómo empiezo? <a class="header-anchor" href="#¿como-empiezo" aria-label="Permalink to &quot;¿Cómo empiezo?&quot;">​</a></h2><ol><li><a href="/manual/guia-inicio/instalacion.html">Cómo ingresar</a> — acceder e iniciar sesión.</li><li><a href="/manual/guia-inicio/primeros-pasos.html">Primeros pasos</a> — recorrido para poner una obra en marcha.</li><li><a href="/manual/guia-inicio/onboarding.html">Registro de una empresa</a> — cómo se da de alta una empresa nueva.</li></ol><h2 id="mapa-de-la-documentacion" tabindex="-1">Mapa de la documentación <a class="header-anchor" href="#mapa-de-la-documentacion" aria-label="Permalink to &quot;Mapa de la documentación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sección</th><th>¿Qué encontrarás?</th></tr></thead><tbody><tr><td><a href="/manual/ds44/">DS44 &amp; Normativa</a></td><td>Qué exige el DS 44 y cómo cumplirlo desde la plataforma.</td></tr><tr><td><a href="/manual/modulos/">Módulos</a></td><td>Guía de uso de cada parte de la plataforma.</td></tr><tr><td><a href="/manual/roles/">Roles</a></td><td>Qué puede hacer cada tipo de usuario.</td></tr></tbody></table>',12)])])}const g=e(i,[["render",n]]);export{p as __pageData,g as default};
